<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)($_SESSION['role']??'');if(!in_array($role,['admin','director','sub_director','headteacher','bursar'],true)){http_response_code(403);exit('Your role cannot view fee invoices.');}$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);$structure=filter_var($_GET['structure_id']??null,FILTER_VALIDATE_INT);if(!$school||!$structure){http_response_code(422);exit('Choose a school and fee structure.');}$db=db();$q=$db->prepare('SELECT s.name school_name,f.id,f.academic_year,f.term,f.title,f.status,c.name class_name FROM schools s JOIN school_memberships m ON m.school_id=s.id AND m.user_id=? JOIN fee_structures f ON f.school_id=s.id AND f.id=? JOIN school_classes c ON c.id=f.class_id AND c.school_id=s.id WHERE s.id=?');$q->execute([$uid,$structure,$school]);$fee=$q->fetch();if(!$fee){http_response_code(404);exit('Fee structure not found in an accessible school.');}$q=$db->prepare('SELECT p.id pupil_id,p.admission_number,p.first_name,p.middle_name,p.last_name,p.status,COUNT(a.id) line_count,COALESCE(SUM(l.amount),0) invoice_total FROM fee_assessments a JOIN pupils p ON p.id=a.pupil_id AND p.school_id=a.school_id JOIN school_fee_ledger l ON l.id=a.ledger_entry_id AND l.school_id=a.school_id AND l.pupil_id=a.pupil_id WHERE a.school_id=? AND a.structure_id=? GROUP BY p.id,p.admission_number,p.first_name,p.middle_name,p.last_name,p.status ORDER BY p.last_name,p.first_name,p.admission_number');$q->execute([$school,$structure]);$pupils=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fee invoices · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><style>@media print{.sidebar,.topbar,.screen-only,.page-footer{display:none!important}.main-area{margin:0!important;padding:0!important}.page-content{max-width:none!important;padding:0!important}.table-wrap{overflow:visible!important}table{min-width:0!important}}</style></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><div class="crumb">School fees <span>/</span> Fee invoices</div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow"><?=e($fee['school_name'])?> · <?=e($fee['class_name'])?> · <?=e($fee['academic_year'].' · '.$fee['term'])?></div><h1>Fee invoices</h1><p class="muted"><?=e($fee['title'])?> · <?=e(ucfirst($fee['status']))?></p></div><a class="button screen-only" href="fee_structures.php?school_id=<?=$school?>">Back to fee structures</a></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ASSESSED PUPILS</div><h2>Invoice register</h2><p class="muted">Invoices are generated only for pupils with ledger-linked assessments.</p></div><span class="count-pill"><?=count($pupils)?> pupils</span></div><?php if($pupils):?><div class="table-wrap"><table><thead><tr><th>Pupil</th><th>Admission no.</th><th>Account status</th><th>Invoice lines</th><th>Assessed (KES)</th><th></th></tr></thead><tbody><?php foreach($pupils as $p):?><tr><td><?=e(trim($p['first_name'].' '.($p['middle_name']??'').' '.$p['last_name']))?></td><td><?=e($p['admission_number'])?></td><td><?=e(ucfirst($p['status']))?></td><td><?=number_format((int)$p['line_count'])?></td><td><?=number_format((float)$p['invoice_total'],2)?></td><td><a class="button" href="fee_invoice.php?school_id=<?=$school?>&amp;structure_id=<?=$structure?>&amp;pupil_id=<?=$p['pupil_id']?>">Print invoice</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No invoices have been assessed</h3><p>Apply this published fee structure to its class to create ledger-backed invoices.</p></div><?php endif;?></section><footer class="page-footer">ShuleLite · Fee invoices</footer></div></main></div></body></html>